import { loadEnv, botToken, watchChannels, AVA_CHANNELS } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';

const MSG_ID = '1533620343216935134';
const BOATS_THREAD = '1533603278816936168';

const env = await loadEnv();
const token = botToken(env);
if (!token) { console.error('no AVA_DISCORD_BOT_TOKEN'); process.exit(1); }
const fetchJson = makeFetchJson(token);

const channels = [BOATS_THREAD, ...watchChannels(env)].filter((v,i,a)=>a.indexOf(v)===i);
console.log('scanning channels:', channels.length, channels.slice(0,15));

let found = null;
let foundCh = null;
for (const ch of channels) {
  try {
    const msg = await fetchJson('/channels/' + ch + '/messages/' + MSG_ID);
    found = msg;
    foundCh = ch;
    console.log('FOUND in', ch);
    break;
  } catch (e) {
    const m = String(e.message||'');
    if (!/404|10008/.test(m)) console.log('err', ch, m.slice(0,120));
  }
}

if (!found) {
  // try around boats thread history for nearby context anyway
  console.log('not found in watch list; dumping boats thread recent...');
  try {
    const hist = await fetchJson('/channels/' + BOATS_THREAD + '/messages?limit=30');
    console.log(JSON.stringify(hist.map(m=>({id:m.id,author:m.author?.username,content:(m.content||'').slice(0,200)})), null, 2));
  } catch (e) { console.log('boats hist fail', e.message); }
  process.exit(2);
}

console.log(JSON.stringify({
  channel_id: found.channel_id || foundCh,
  id: found.id,
  author: { id: found.author?.id, username: found.author?.username, global_name: found.author?.global_name, bot: found.author?.bot },
  content: found.content,
  timestamp: found.timestamp,
  referenced_message: found.referenced_message ? { id: found.referenced_message.id, author: found.referenced_message.author?.username, content: (found.referenced_message.content||'').slice(0,300) } : null,
  mentions: (found.mentions||[]).map(u=>({id:u.id,username:u.username})),
  reactions: found.reactions,
}, null, 2));

// nearby context
const around = await fetchJson('/channels/' + foundCh + '/messages?limit=25&around=' + MSG_ID);
console.log('---AROUND---');
for (const m of around) {
  console.log(m.id, m.author?.username + ':' , (m.content||'').replace(/\n/g,' | ').slice(0,280));
}
"

