const base = String(process.env.AVA_API_BASE || process.env.ROOTMC_API_BASE || 'https://api.rootmc.net').replace(/\/$/,'');
console.log('has workstation key', !!key);

// try common endpoints
for (const path of [
  '/api/governance/voting-power?discord_user_id=' + alexDiscord,
  '/api/internal/listing-votes?discord_user_id=' + alexDiscord,
]) {
  try {
    const res = await fetch(base + path, {
      headers: {
        Accept: 'application/json',
        'User-Agent': 'AvaIvyRootMC/0.5',
        ...(key ? { 'X-RootMC-Dev-Key': key } : {}),
      },
    });
    const text = await res.text();
    console.log(path, res.status, text.slice(0, 800));
  } catch (e) {
    console.log(path, e.message);
  }
}
